void Solver::bump_var(int var, double coeff) {
    // Compute increment and update activity
    double inc = var_inc * coeff;
    activity[var] += inc;

    // Prevent activity overflow by rescaling all activities if a threshold is exceeded
    const double ACTIVITY_LIMIT = 1e150;
    if (activity[var] > ACTIVITY_LIMIT) {
        double scale = 1e-150;
        for (int i = 1; i <= vars; ++i) {
            activity[i] *= scale;
        }
        var_inc *= scale;
    }

    // Keep the VSIDS heap consistent
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}

